SELECT id, tenant_id, work_type, title, status_node_id, creator_id, gmt_create
FROM workitem
WHERE tenant_id = #{tenantId}
  AND is_deleted = 0
  AND title LIKE CONCAT('%', #{title}, '%')
AND id != #{excludeId}
ORDER BY id DESC
LIMIT #{limit}

SELECT id, title
FROM workitem
WHERE tenant_id = #{tenantId}
  AND is_deleted = 0
  AND gmt_create >= #{since}
  AND gmt_create <= #{through}
AND id != #{excludeId}
ORDER BY id ASC

