mapper.select:
SELECT COUNT(*) FROM workitem w
INNER JOIN status_node sn ON sn.id = w.status_node_id
WHERE w.is_deleted = 0
  AND w.assignee_type = #{assigneeType}
  AND w.assignee_ref = #{assigneeRef}
  AND sn.category NOT IN ('DONE', 'CANCELED')

